package docs

import (
	"archive/zip"
	"bytes"
	"encoding/xml"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// An .xlsx is a zip of XML, the same shape as the workbook Ptium writes behind
// every exported chart. Reading one needs no library: the sheets are rows of
// cells, the strings are in one shared table, and everything else on the sheet
// — formatting, formulas, pivot caches — is not what a deck is made of.

type workbookIndex struct {
	Properties struct {
		Date1904 string `xml:"date1904,attr"`
	} `xml:"workbookPr"`
	Sheets struct {
		Sheet []struct {
			Name  string `xml:"name,attr"`
			ID    string `xml:"id,attr"`
			State string `xml:"state,attr"`
		} `xml:"sheet"`
	} `xml:"sheets"`
}

type workbookRelationships struct {
	Relationship []struct {
		ID     string `xml:"Id,attr"`
		Target string `xml:"Target,attr"`
	} `xml:"Relationship"`
}

type sharedStrings struct {
	Items []struct {
		Text string   `xml:"t"`
		Runs []string `xml:"r>t"`
	} `xml:"si"`
}

type worksheet struct {
	// A sheet says which of its columns are hidden ahead of its rows, as
	// ranges: "min" to "max", counted from one.
	Columns []struct {
		Min    int    `xml:"min,attr"`
		Max    int    `xml:"max,attr"`
		Hidden string `xml:"hidden,attr"`
	} `xml:"cols>col"`
	Rows []struct {
		Reference string `xml:"r,attr"`
		Hidden    string `xml:"hidden,attr"`
		Cells     []struct {
			Reference  string   `xml:"r,attr"`
			Type       string   `xml:"t,attr"`
			Style      string   `xml:"s,attr"`
			Value      string   `xml:"v"`
			Inline     string   `xml:"is>t"`
			InlineRuns []string `xml:"is>r>t"`
		} `xml:"c"`
	} `xml:"sheetData>row"`
}

// readWorkbook reads a spreadsheet into slides, one per sheet.
func readWorkbook(filename string, data []byte) (Document, error) {
	archive, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return Document{}, fmt.Errorf("이 파일은 엑셀 통합 문서가 아닙니다")
	}
	parts := map[string][]byte{}
	for _, file := range archive.File {
		opened, err := file.Open()
		if err != nil {
			continue
		}
		content, err := io.ReadAll(io.LimitReader(opened, 32<<20))
		opened.Close()
		if err == nil {
			parts[file.Name] = content
		}
	}
	var index workbookIndex
	if err := xml.Unmarshal(parts["xl/workbook.xml"], &index); err != nil || len(index.Sheets.Sheet) == 0 {
		return Document{}, fmt.Errorf("이 통합 문서에서 시트를 찾지 못했습니다")
	}
	var relationships workbookRelationships
	_ = xml.Unmarshal(parts["xl/_rels/workbook.xml.rels"], &relationships)
	target := map[string]string{}
	for _, relationship := range relationships.Relationship {
		target[relationship.ID] = strings.TrimPrefix(relationship.Target, "/")
	}
	var strings0 sharedStrings
	_ = xml.Unmarshal(parts["xl/sharedStrings.xml"], &strings0)
	// What each style means, so a date is a day and a per cent is a per cent —
	// and which day the workbook counts its days from, so the day is the one on
	// the sheet.
	formats := readCellFormats(parts["xl/styles.xml"], counts1904(index.Properties.Date1904))
	shared := make([]string, 0, len(strings0.Items))
	for _, item := range strings0.Items {
		if item.Text != "" {
			shared = append(shared, item.Text)
			continue
		}
		shared = append(shared, strings.Join(item.Runs, ""))
	}

	document := Document{Title: titleOf(filename)}
	var builder strings.Builder
	fmt.Fprintf(&builder, "# %s\n@cover\n> %s\n\n", escapeLine(document.Title), escapeLine(filename))
	written := 0
	var warnings []string
	var hidden []string
	var left []string
	for _, sheet := range index.Sheets.Sheet {
		// A workbook says which of its sheets it hides, and a hidden sheet is
		// one nobody meant anyone to see: the code table a formula looks up in,
		// the settings a macro reads, last quarter's working copy. Taken as if
		// it were visible, it became a slide in the middle of the deck.
		if sheetHidden(sheet.State) {
			hidden = append(hidden, sheet.Name)
			continue
		}
		name := target[sheet.ID]
		if name == "" {
			continue
		}
		content, ok := parts[sheetPart(name)]
		if !ok {
			continue
		}
		var parsed worksheet
		if err := xml.Unmarshal(content, &parsed); err != nil {
			continue
		}
		rows, at, hiddenRows, hiddenColumns := onScreen(parsed, gridOf(parsed, shared, formats))
		// A deck holds so many slides, and a workbook of forty sheets runs out
		// of deck before it runs out of sheets. What was left out is what the
		// person who uploaded it has to know, and naming it is the only way
		// they can: "시트가 많아 앞 30개만 가져왔습니다" named neither, and the
		// number in it was how many slides a deck holds — so a workbook whose
		// sheets each fill three slides said it had taken the first thirty of
		// its eleven. A sheet with nothing on it was never going to be a
		// slide, so it is not something that was left out.
		if written >= maximumSlides {
			if len(trimGrid(rows)) >= 2 {
				left = append(left, sheet.Name)
			}
			continue
		}
		count, sheetWarnings := writeSheet(&builder, filename, sheet.Name, rows, at)
		written += count
		warnings = append(warnings, sheetWarnings...)
		// What was hidden is worth a line only under a slide it was hidden
		// from; a sheet that made no slide left nothing out of one.
		if count > 0 {
			if concealed := concealedNamed(hiddenRows, hiddenColumns); concealed != "" {
				warnings = append(warnings, fmt.Sprintf("%s의 숨긴 %s 가져오지 않았습니다",
					sheetLabel(filename, sheet.Name), concealed))
			}
		}
	}
	if written == 0 {
		// Why there is nothing to show matters when the file plainly has
		// figures in it: "읽을 표가 없습니다" sends someone back to a workbook
		// they can see the numbers in, to look for what is wrong with it.
		if len(hidden) > 0 {
			return Document{}, fmt.Errorf("이 통합 문서의 시트(%s)는 모두 숨겨져 있습니다",
				sheetsNamed(hidden))
		}
		return Document{}, fmt.Errorf("이 통합 문서에는 읽을 표가 없습니다")
	}
	if len(left) > 0 {
		warnings = append(warnings, fmt.Sprintf(
			"슬라이드가 많아 시트(%s)는 가져오지 않았습니다. 나눠서 올리면 전부 가져옵니다",
			sheetsNamed(left)))
	}
	if len(hidden) > 0 {
		warnings = append(warnings, fmt.Sprintf("숨겨진 시트(%s)는 가져오지 않았습니다",
			sheetsNamed(hidden)))
	}
	document.Source = builder.String()
	document.Warnings = warnings
	return document, nil
}

// sheetHidden reports whether a workbook hides a sheet. "veryHidden" is the
// one only a macro can put back, which is further from being meant for a deck
// rather than nearer; anything else, including the state a sheet writes by
// writing nothing, is a sheet somebody looks at.
func sheetHidden(state string) bool {
	switch strings.ToLower(strings.TrimSpace(state)) {
	case "hidden", "veryhidden":
		return true
	}
	return false
}

// sheetsNamed writes the sheets a warning is about, named while naming them is
// what somebody can act on.
//
// A warning is one line that somebody reads. Forty names is the workbook's
// table of contents written into that line, and the ones at the end of it are
// the ones that go off the edge; past a handful, how many there are is the
// part that can be acted on, and the first few say which end of the workbook
// they came from.
func sheetsNamed(names []string) string {
	const named = 5
	if len(names) <= named {
		return strings.Join(names, ", ")
	}
	return fmt.Sprintf("%s 외 %d개", strings.Join(names[:named], ", "), len(names)-named)
}

// counts1904 reports whether a workbook counts its days from 1904 rather than
// from 1900, which is what Excel for the Macintosh wrote and what a workbook
// keeps doing however it is opened afterwards.
//
// The switch is written the way the format writes every switch: "1" or "true",
// and a workbook that says nothing counts from 1900.
func counts1904(value string) bool {
	return switchedOn(value)
}

// switchedOn reads a switch the way the format writes every one of them: "1"
// or "true" is on, and anything else, including nothing, is off.
func switchedOn(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "1", "true":
		return true
	}
	return false
}

// onScreen keeps of a sheet's grid what is on the screen: the rows and columns
// the sheet does not hide. It reports where on the sheet what it kept was, and
// how many rows and columns it left out.
//
// A sheet hides rows and columns for the same reasons a workbook hides sheets
// — the rows a filter took out of view, the group somebody folded up, the
// column of codes a formula looks up in — and they were as much not meant for
// a deck. Read in, a hidden column of figures beside the one column of them
// that was meant to be seen made the sheet a table where a chart was wanted,
// and a hidden column of anything sat in the middle of the table where nobody
// had seen it. Hidden columns are cut out rather than blanked, since a blank
// column in the middle of a table is not trimmed and would stay there.
//
// What is counted is what was on the screen to hide: a hidden row with no
// cell in it, or a hidden column no shown row writes anything in, was never
// going to be in the table either way, and counting it would put a number in
// the warning that nobody can find on the sheet. Excel hides columns to the
// edge of the sheet in one range, and that range is not sixteen thousand
// columns of anything.
//
// The ranges are kept as the ranges they were written as and asked about one
// column of the grid at a time. Spread out into every column they cover, they
// were sixteen thousand entries for the range Excel writes, and as many as a
// file cared to say for the range a file wrote: a sheet of six cells hiding
// columns C through four billion was enough to run the server out of memory.
// The grid's own width is the only thing here worth paying for.
func onScreen(sheet worksheet, grid [][]string) (rows [][]string, at placement, hiddenRows, hiddenColumns int) {
	rows = make([][]string, 0, len(grid))
	width := 0
	for index, line := range grid {
		// gridOf writes one line for each row, in the row's order.
		if index < len(sheet.Rows) && switchedOn(sheet.Rows[index].Hidden) {
			if !blankLine(line) {
				hiddenRows++
			}
			continue
		}
		rows = append(rows, line)
		at.rows = append(at.rows, index)
		width = max(width, len(line))
	}
	var ranges [][2]int
	for _, column := range sheet.Columns {
		// A range with no bounds, or bounds the wrong way round, is a column
		// setting that names no column, and hides none.
		if !switchedOn(column.Hidden) || column.Min < 1 || column.Max < column.Min {
			continue
		}
		ranges = append(ranges, [2]int{column.Min - 1, column.Max - 1})
	}
	if len(ranges) == 0 {
		return rows, at, hiddenRows, 0
	}
	hidden := func(column int) bool {
		for _, span := range ranges {
			if column >= span[0] && column <= span[1] {
				return true
			}
		}
		return false
	}
	for column := 0; column < width; column++ {
		if !hidden(column) {
			at.columns = append(at.columns, column)
		}
	}
	written := map[int]bool{}
	for index, line := range rows {
		kept := make([]string, 0, len(line))
		for column, value := range line {
			if !hidden(column) {
				kept = append(kept, value)
				continue
			}
			if strings.TrimSpace(value) != "" {
				written[column] = true
			}
		}
		rows[index] = kept
	}
	return rows, at, hiddenRows, len(written)
}

// blankLine reports whether a row of the grid has nothing written in it.
func blankLine(line []string) bool {
	for _, value := range line {
		if strings.TrimSpace(value) != "" {
			return false
		}
	}
	return true
}

// concealedNamed writes what a sheet hid, for the warning that says so: rows,
// columns, or both, and nothing when nothing was hidden. The phrase ends in a
// count, and the particle that follows a count is always the same one, so it
// is written here rather than chosen in the warning for a phrase it cannot see.
func concealedNamed(rows, columns int) string {
	var parts []string
	if rows > 0 {
		parts = append(parts, fmt.Sprintf("행 %d개", rows))
	}
	if columns > 0 {
		parts = append(parts, fmt.Sprintf("열 %d개", columns))
	}
	if len(parts) == 0 {
		return ""
	}
	return strings.Join(parts, "와 ") + "는"
}

// sheetPart joins a workbook-relative part name, which may already be absolute.
func sheetPart(name string) string {
	if strings.HasPrefix(name, "xl/") {
		return name
	}
	return "xl/" + name
}

// gridOf reads a sheet into rows of text, in the cells' own positions: a sheet
// leaves out empty cells, and reading them in order would shift a row left.
//
// The position is in the cell's own reference where it has one. It is allowed
// not to have one — the reference is optional, and the writers that stream a
// sheet out row by row leave it off — and then the cell is simply the next one
// along. Reading a missing reference as column A instead put every cell of the
// row in the same place and kept the last: a two-column sheet came back as one
// column of figures with the labels gone, and the deck said nothing about it.
func gridOf(sheet worksheet, shared []string, formats cellFormats) [][]string {
	grid := make([][]string, 0, len(sheet.Rows))
	for _, row := range sheet.Rows {
		cells := map[int]string{}
		widest := -1
		next := 0
		for _, cell := range row.Cells {
			column := columnOf(cell.Reference)
			if column < 0 {
				column = next
			}
			next = column + 1
			value := cell.Value
			switch cell.Type {
			case "s":
				if index, err := strconv.Atoi(strings.TrimSpace(cell.Value)); err == nil && index >= 0 && index < len(shared) {
					value = shared[index]
				}
			case "inlineStr":
				value = cell.Inline
				if value == "" {
					value = strings.Join(cell.InlineRuns, "")
				}
			case "b":
				// A logical cell stores TRUE as 1 and FALSE as 0, and the sheet
				// shows the word. Read as the number it stores, a checklist came
				// back as a column of 0s and 1s and was drawn as a bar chart of
				// them; with a format on the cell it was worse, because 1 under a
				// date format is a day and 0 under a per cent is "0%".
				value = truthOf(cell.Value)
			case "d":
				// A workbook written to the strict schema keeps a date as the
				// date, not as a count of days. It is the format that says how
				// much of it the sheet shows, the same as for a count.
				if shown, ok := formats.moment(cell.Style, value); ok {
					value = shown
				}
			case "str", "e":
				// A formula's cached result: text, or the error it ended in.
				// Neither is a number, so neither is a day or a per cent —
				// a formula that returned the characters "45678" into a
				// date-formatted cell is not 2025-01-21.
			default:
				// A number carries its meaning in its format: a day counted
				// from 1899-12-30, or a fraction of one written as a per cent.
				if shown, ok := formats.written(cell.Style, value); ok {
					value = shown
				}
			}
			cells[column] = strings.TrimSpace(value)
			if column > widest {
				widest = column
			}
		}
		line := make([]string, widest+1)
		for column, value := range cells {
			if column >= 0 && column <= widest {
				line[column] = value
			}
		}
		grid = append(grid, line)
	}
	return grid
}

// truthOf writes a logical cell the way a spreadsheet shows it. Anything that
// is neither of the two things a logical cell can store is left as it is.
func truthOf(value string) string {
	switch strings.TrimSpace(value) {
	case "1":
		return "TRUE"
	case "0":
		return "FALSE"
	}
	return value
}

// columnOf reads the column out of a cell reference such as "BC12", and
// returns -1 for a reference that names no column at all.
func columnOf(reference string) int {
	column := 0
	for _, symbol := range strings.ToUpper(strings.TrimSpace(reference)) {
		if symbol < 'A' || symbol > 'Z' {
			break
		}
		column = column*26 + int(symbol-'A') + 1
	}
	if column <= 0 {
		return -1
	}
	return column - 1
}
package docs

import (
	"encoding/csv"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// A spreadsheet is a deck's numbers, already gathered.
//
// What it is not is a deck: a hundred rows on one slide is a picture of a
// spreadsheet. So a sheet becomes what a person would draw from it — a chart
// when it is one series of figures against labels, a table otherwise — and the
// slide says which file and which range it came from.

// readSeparated reads a CSV or TSV file.
func readSeparated(filename string, data []byte, separator rune) (Document, error) {
	rows, forgiven, err := separatedRows(strings.TrimPrefix(string(data), "\ufeff"), separator)
	if err != nil {
		return Document{}, err
	}
	document := Document{Title: titleOf(filename)}
	var builder strings.Builder
	fmt.Fprintf(&builder, "# %s\n@cover\n> %s\n\n", escapeLine(document.Title), escapeLine(filename))
	written, warnings := writeSheet(&builder, filename, "", rows, placement{})
	if written == 0 {
		return Document{}, fmt.Errorf("이 파일에는 읽을 표가 없습니다")
	}
	document.Source = builder.String()
	if forgiven > 0 {
		document.Warnings = append(document.Warnings, fmt.Sprintf(
			"%s의 %d번째 줄에 짝이 없는 따옴표가 있어 글자 그대로 읽었습니다", filename, forgiven))
	}
	document.Warnings = append(document.Warnings, warnings...)
	return document, nil
}

// separatedRows reads the rows, and says which line's quote it had to forgive.
//
// A quote in a field nobody quoted is not a broken file. An export writes
// 15" 모니터, or a width as 21", and the strict reader stops the whole file at
// that one character: five hundred rows refused over a Korean sentence with an
// English parser message inside it, naming a line and a column nobody can act
// on. So a file the strict reader will not take is read again with the quote
// taken literally, and the line it was on is said as a warning instead — in
// case what is written there was meant to be a quoted field after all.
func separatedRows(text string, separator rune) ([][]string, int, error) {
	rows, strict := separatedReader(text, separator, false).ReadAll()
	if strict == nil {
		return rows, 0, nil
	}
	lazy, err := separatedReader(text, separator, true).ReadAll()
	if err != nil {
		return nil, 0, fmt.Errorf("이 파일을 표로 읽지 못했습니다: %w", strict)
	}
	// The line the record started on, not the one the reader gave up on: a
	// quote that never closes is a mistake where it was opened, and the reader
	// runs to the end of the file before it says anything.
	line := 1
	var parse *csv.ParseError
	if errors.As(strict, &parse) {
		if parse.StartLine > 0 {
			line = parse.StartLine
		} else if parse.Line > 0 {
			line = parse.Line
		}
	}
	return lazy, line, nil
}

func separatedReader(text string, separator rune, lazy bool) *csv.Reader {
	reader := csv.NewReader(strings.NewReader(text))
	reader.Comma = separator
	// A ragged file is normal: someone's export has a trailing note, or a blank
	// column. Reading it is better than refusing it.
	reader.FieldsPerRecord = -1
	reader.LazyQuotes = lazy
	return reader
}

// placement is where a grid's rows and columns are on the sheet it was read
// from, when the grid is not the whole sheet: what was hidden was cut out of
// the grid, but a slide's source is a place on the sheet, and the place has
// the hidden rows and columns in it. A placement that says nothing is a grid
// that is the sheet, row for row and column for column.
type placement struct {
	rows, columns []int
}

// row is the sheet's row, counted from zero, that a row of the grid was.
func (p placement) row(index int) int {
	if index >= 0 && index < len(p.rows) {
		return p.rows[index]
	}
	return index
}

// column is the sheet's column, counted from zero, that a column of the grid was.
func (p placement) column(index int) int {
	if index >= 0 && index < len(p.columns) {
		return p.columns[index]
	}
	return index
}

// writeSheet turns a grid into slides, and returns how many it wrote.
func writeSheet(builder *strings.Builder, filename, sheet string, rows [][]string, from placement) (int, []string) {
	rows, kept := trimmed(rows)
	if len(rows) < 2 {
		return 0, nil
	}
	var warnings []string
	columns := len(rows[0])
	if columns > maximumColumns {
		columns = maximumColumns
		warnings = append(warnings, fmt.Sprintf("%s의 열이 많아 앞 %d개만 가져왔습니다",
			sheetLabel(filename, sheet), maximumColumns))
	}
	// The source of a slide reaches to the last column and, given which row
	// of the grid is the last one on the slide, the last row — where each of
	// them was on the sheet.
	source := func(last int) string {
		return rangeOf(sheet, from.column(columns-1), from.row(kept[last]))
	}
	// A sheet longer than a slide holds continues on the next one rather than
	// stopping at the eighth row: a twelve-row report table is a table, not the
	// first eight rows of one. Past a few slides it is a spreadsheet rather than
	// a deck, and what is left is said instead of drawn.
	all := rows[1:]
	body := all
	var carried [][][]string
	if len(body) > maximumRows {
		body = all[:maximumRows]
		for at := maximumRows; at < len(all) && len(carried) < maximumTableSlides-1; at += maximumRows {
			end := min(at+maximumRows, len(all))
			carried = append(carried, all[at:end])
		}
		if written := maximumRows + len(carried)*maximumRows; written < len(all) {
			warnings = append(warnings, fmt.Sprintf("%s의 행이 많아 앞 %d줄만 가져왔습니다",
				sheetLabel(filename, sheet), written))
		}
	}

	heading := strings.TrimSpace(sheet)
	if heading == "" {
		heading = titleOf(filename)
	}
	fmt.Fprintf(builder, "# %s\n", escapeLine(heading))
	// One label column and one column of figures is a chart, which is what a
	// person would draw. Anything wider is a table.
	if columns == 2 && allNumeric(body, 1) {
		fmt.Fprintf(builder, "::columns %s\n", escapeLine(strings.TrimSpace(rows[0][1])))
		for _, row := range body {
			fmt.Fprintf(builder, "- %s | %s\n", escapeField(row[0]), escapeField(row[1]))
		}
	} else {
		fmt.Fprintf(builder, "::table %s\n", escapeLine(strings.TrimSpace(rows[0][0])))
		for _, row := range append([][]string{rows[0]}, body...) {
			fields := make([]string, 0, columns)
			for index := 0; index < columns; index++ {
				value := ""
				if index < len(row) {
					value = row[index]
				}
				fields = append(fields, escapeField(value))
			}
			fmt.Fprintf(builder, "- %s\n", strings.Join(fields, " | "))
		}
	}
	builder.WriteString("::\n")
	// The heading is row 0 of the grid, so the last row of the slide is one
	// past the number of body rows on it.
	last := len(body)
	builder.WriteString(citation(filename, source(last)))
	builder.WriteString("\n")
	written := 1
	for _, piece := range carried {
		fmt.Fprintf(builder, "# %s (계속)\n", escapeLine(heading))
		if columns == 2 && allNumeric(piece, 1) {
			fmt.Fprintf(builder, "::columns %s\n", escapeLine(strings.TrimSpace(rows[0][1])))
			for _, row := range piece {
				fmt.Fprintf(builder, "- %s | %s\n", escapeField(row[0]), escapeField(row[1]))
			}
		} else {
			fmt.Fprintf(builder, "::table %s\n", escapeLine(strings.TrimSpace(rows[0][0])))
			for _, row := range append([][]string{rows[0]}, piece...) {
				fields := make([]string, 0, columns)
				for index := 0; index < columns; index++ {
					value := ""
					if index < len(row) {
						value = row[index]
					}
					fields = append(fields, escapeField(value))
				}
				fmt.Fprintf(builder, "- %s\n", strings.Join(fields, " | "))
			}
		}
		builder.WriteString("::\n")
		last += len(piece)
		builder.WriteString(citation(filename, source(last)))
		builder.WriteString("\n")
		written++
	}
	return written, warnings
}

func sheetLabel(filename, sheet string) string {
	if strings.TrimSpace(sheet) == "" {
		return filename
	}
	return sheet
}

// rangeOf is where on the sheet the slide came from, written the way a
// spreadsheet writes it: "Sheet1!A1:C9", given the last column and the last
// row of the slide as the sheet counts them, from zero.
func rangeOf(sheet string, column, row int) string {
	reference := fmt.Sprintf("A1:%s%d", columnLetter(column), max(row, 0)+1)
	if sheet := strings.TrimSpace(sheet); sheet != "" {
		return sheet + "!" + reference
	}
	return reference
}

func columnLetter(index int) string {
	if index < 0 {
		index = 0
	}
	if index < 26 {
		return string(rune('A' + index))
	}
	return string(rune('A'+index/26-1)) + string(rune('A'+index%26))
}

// trimGrid drops empty rows and trailing empty columns, which every export has.
func trimGrid(rows [][]string) [][]string {
	cleaned, _ := trimmed(rows)
	return cleaned
}

// trimmed is trimGrid that also says, for each row it kept, which row of the
// grid it was.
func trimmed(rows [][]string) ([][]string, []int) {
	widest := 0
	cleaned := make([][]string, 0, len(rows))
	kept := make([]int, 0, len(rows))
	for at, row := range rows {
		last := -1
		for index, cell := range row {
			if strings.TrimSpace(cell) != "" {
				last = index
			}
		}
		if last < 0 {
			continue
		}
		row = row[:last+1]
		widest = max(widest, len(row))
		cleaned = append(cleaned, row)
		kept = append(kept, at)
	}
	for index, row := range cleaned {
		for len(row) < widest {
			row = append(row, "")
		}
		cleaned[index] = row
	}
	return cleaned, kept
}

// allNumeric reports whether every row carries a number in a column.
//
// This is the question that sends a sheet on as a chart, and the answer has to
// stay no wider than what the deck's own parser (deck.parseNumber) can read
// back out of the same cell. The two are separate readings on purpose — the
// deck's one keeps a contract this one does not, that a figure ends at a space,
// which is what lets a line chart's row hold four of them — so widening this
// one past that is how a column gets called figures and then handed bar heights
// nobody wrote.
func allNumeric(rows [][]string, column int) bool {
	found := false
	for _, row := range rows {
		if column >= len(row) {
			return false
		}
		value := strings.TrimSpace(row[column])
		if value == "" {
			return false
		}
		if _, ok := amountOf(value); !ok {
			return false
		}
		found = true
	}
	return found
}

// amountOf reads a figure the way a sheet of money writes one.
//
// A column of amounts is a column of figures, but a spreadsheet almost never
// writes them bare. The Currency format puts a sign on every row — "₩1,200" in
// Korea, "$1,200" elsewhere, "1,200원" where the currency is a word. None of
// that is text a person put there; it is how the sheet shows the number. Read
// as text, one such column was not a column of figures, so a two-column sheet
// of sales by region came out as a table of the very numbers somebody opened it
// to see drawn.
//
// Only the signs come off, and a unit that is a word stays: "1월" is a month
// and "3개" is a count of things, and neither is a figure to plot an axis by.
// A space between the figure and its unit comes off with the unit, but a space
// inside the figure does not: the deck's parser ends a figure at any space, so
// "1 200" — how a sheet in a good many countries writes a thousand — is 1,200
// here and 1 on the bar, and the sheet is worse off as a chart of heights
// nobody wrote than as the table it was. Where the two readings disagree, this
// one gives way.
//
// The accounting bracket — "(340)", how a sheet writes a refund — is the same
// disagreement and stays out for the same reason. A bar is laid out by its
// magnitude, so a refund read as -340 is drawn in the direction and at the
// height of a month that sold 340, and the minus survives only in a value label
// the chart drops once it holds more than six bars. A column with a refund in
// it is left the table it was, where the brackets are still on the page.
// commaIsNotAThousandsSeparator reports whether a comma in the written figure is
// doing something other than grouping thousands — which, in practice, means the
// sheet is written in a locale where the comma is the decimal point.
//
// It matters because amountSigns strips commas outright. "1,200" is 1200 either
// way, but "€1.234,56" becomes "1.23456" and draws a bar a thousandth of its
// height, and the reader has no way to see that the number on the page is not
// the number on the chart. Before the European signs were added here such a cell
// was no figure at all and the sheet stayed a table, which was the safe answer.
//
// A comma that groups thousands is always followed by exactly three digits, and
// a sheet does not use both separators for grouping. Anything else is a locale
// this reader cannot tell apart, so it gives way — the same rule the space
// thousands form is excluded under.
func commaIsNotAThousandsSeparator(value string) bool {
	if !strings.Contains(value, ",") {
		return false
	}
	// Both separators present: whichever comes last is the decimal point.
	// "1,234.56" is English and reads correctly; "1.234,56" is not.
	if dot := strings.LastIndex(value, "."); dot >= 0 {
		return strings.LastIndex(value, ",") > dot
	}
	for index := strings.Index(value, ","); index >= 0; {
		digits := 0
		for position := index + 1; position < len(value) && value[position] >= '0' && value[position] <= '9'; position++ {
			digits++
		}
		if digits != 3 {
			return true
		}
		next := strings.Index(value[index+1:], ",")
		if next < 0 {
			break
		}
		index = index + 1 + next
	}
	return false
}

func amountOf(value string) (float64, bool) {
	if commaIsNotAThousandsSeparator(strings.TrimSpace(value)) {
		return 0, false
	}
	cleaned := strings.TrimSpace(amountSigns.Replace(strings.TrimSpace(value)))
	if !bareFigure(cleaned) {
		return 0, false
	}
	number, err := strconv.ParseFloat(cleaned, 64)
	if err != nil {
		return 0, false
	}
	return number, true
}

// bareFigure reports whether what is left once the signs are off is a figure
// the deck's parser reads to the end: a sign, digits, and at most one decimal
// point after a digit, and nothing else.
//
// This is the same giving way, spelt out. Go's own reading of a number is wider
// than the deck's — it takes the exponent a spreadsheet writes a large amount
// with ("1.5E+15", which is how the file itself holds a figure that long), and
// it takes "Inf" and "NaN" besides. The deck's parser stops at the letter, so a
// column of those is one this would call figures and the chart would then draw
// at 1.5. Whatever the two cannot read alike is left the table it was.
func bareFigure(text string) bool {
	digits := false
	point := false
	for index, character := range text {
		switch {
		case character >= '0' && character <= '9':
			digits = true
		case character == '.' && digits && !point:
			point = true
		case (character == '-' || character == '+') && index == 0:
		default:
			return false
		}
	}
	return digits
}

// The marks a spreadsheet puts on a figure without changing what the figure is:
// the thousands separator and the per-cent sign a column already carried, and
// the currency signs.
//
// No space is among them, plain or fixed (U+00A0), though a spreadsheet writes
// both — one between a figure and its unit, which comes off with the trimming
// that follows the replacing, and one inside the figure as the thousands
// separator, which must not come off at all. Taking a space off here while the
// deck's parser ends a figure at it is what read "1 200" as 1,200 on the way in
// and drew it as 1 on the way out, a bar an eighth of a per cent tall. Left in
// place, such a column is no figure column and the sheet stays the table it is.
var amountSigns = strings.NewReplacer(
	",", "", "%", "",
	"₩", "", "￦", "", "$", "", "€", "", "£", "", "¥", "", "￥", "", "원", "",
)

}

// counts1904 reports whether a workbook counts its days from 1904 rather than
// from 1900, which is what Excel for the Macintosh wrote and what a workbook
// keeps doing however it is opened afterwards.
//
// The switch is written the way the format writes every switch: "1" or "true",
// and a workbook that says nothing counts from 1900.
func counts1904(value string) bool {
	return switchedOn(value)
}

// switchedOn reads a switch the way the format writes every one of them: "1"
// or "true" is on, and anything else, including nothing, is off.
func switchedOn(value string) bool {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "1", "true":
		return true
	}
	return false
}

// onScreen keeps of a sheet's grid what is on the screen: the rows and columns
// the sheet does not hide. It reports where on the sheet what it kept was, and
// how many rows and columns it left out.
//
// A sheet hides rows and columns for the same reasons a workbook hides sheets
// — the rows a filter took out of view, the group somebody folded up, the
// column of codes a formula looks up in — and they were as much not meant for
// a deck. Read in, a hidden column of figures beside the one column of them
// that was meant to be seen made the sheet a table where a chart was wanted,
// and a hidden column of anything sat in the middle of the table where nobody
// had seen it. Hidden columns are cut out rather than blanked, since a blank
// column in the middle of a table is not trimmed and would stay there.
//
// What is counted is what was on the screen to hide: a hidden row with no
// cell in it, or a hidden column no shown row writes anything in, was never
// going to be in the table either way, and counting it would put a number in
// the warning that nobody can find on the sheet. Excel hides columns to the
// edge of the sheet in one range, and that range is not sixteen thousand
// columns of anything.
//
// The ranges are kept as the ranges they were written as and asked about one
// column of the grid at a time. Spread out into every column they cover, they
// were sixteen thousand entries for the range Excel writes, and as many as a
// file cared to say for the range a file wrote: a sheet of six cells hiding
// columns C through four billion was enough to run the server out of memory.
// The grid's own width is the only thing here worth paying for.
func onScreen(sheet worksheet, grid [][]string) (rows [][]string, at placement, hiddenRows, hiddenColumns int) {
	rows = make([][]string, 0, len(grid))
	width := 0
	for index, line := range grid {
		// gridOf writes one line for each row, in the row's order.
		if index < len(sheet.Rows) && switchedOn(sheet.Rows[index].Hidden) {
			if !blankLine(line) {
				hiddenRows++
			}
			continue
		}
		rows = append(rows, line)
		at.rows = append(at.rows, index)
		width = max(width, len(line))
	}
	var ranges [][2]int
	for _, column := range sheet.Columns {
		// A range with no bounds, or bounds the wrong way round, is a column
		// setting that names no column, and hides none.
		if !switchedOn(column.Hidden) || column.Min < 1 || column.Max < column.Min {
			continue
		}
		ranges = append(ranges, [2]int{column.Min - 1, column.Max - 1})
	}
	if len(ranges) == 0 {
		return rows, at, hiddenRows, 0
	}
	hidden := func(column int) bool {
		for _, span := range ranges {
			if column >= span[0] && column <= span[1] {
				return true
			}
		}
		return false
	}
	for column := 0; column < width; column++ {
		if !hidden(column) {
			at.columns = append(at.columns, column)
		}
	}
	written := map[int]bool{}
	for index, line := range rows {
		kept := make([]string, 0, len(line))
		for column, value := range line {
			if !hidden(column) {
